PROGRAM Main
VAR
  Motor : BOOL;
  Start : BOOL;
  Stop : BOOL;
END_VAR

Motor := Start OR (Motor AND NOT Stop);

END_PROGRAM

PROGRAM Main
VAR
  Motor : BOOL;
  Start : BOOL;
  Auto : BOOL;
  Stop : BOOL;
END_VAR

Motor := Start OR (Motor AND Auto AND NOT Stop);

END_PROGRAM

PROGRAM Main
VAR
  Motor : BOOL;
  Stop : BOOL;
  Start : BOOL;
END_VAR

Motor := (Motor AND NOT Stop) OR Start;

END_PROGRAM

PROGRAM Main
VAR
  ConveyorMotor : BOOL;
  StartPB : BOOL;
  StopPB : BOOL;
END_VAR

ConveyorMotor := StartPB OR (NOT StopPB AND ConveyorMotor);

END_PROGRAM

PROGRAM Main
VAR
  Motor : BOOL;
  Start : BOOL;
  Stop : BOOL;
END_VAR

Motor := Start OR Motor AND NOT Stop;

END_PROGRAM

PROGRAM Main
VAR
  PumpRun : BOOL;
  StartPB : BOOL;
  StopPB : BOOL;
  Overload : BOOL;
END_VAR

PumpRun := StartPB OR (PumpRun AND NOT StopPB AND NOT Overload);

END_PROGRAM

PROGRAM Main
VAR
  Conveyor : BOOL;
  Start : BOOL;
  Stop : BOOL;
  Maintenance : BOOL;
END_VAR

Conveyor := Start OR (Conveyor AND (NOT Stop OR Maintenance));

END_PROGRAM

PROGRAM Main
VAR
  Motor : BOOL;
  Start : BOOL;
  EStop : BOOL;
  Stop : BOOL;
  GuardClosed : BOOL;
END_VAR

Motor := Start OR (Motor AND NOT EStop AND NOT Stop AND GuardClosed);

END_PROGRAM

PROGRAM Main
VAR
  Motor : BOOL;
  Start : BOOL;
  Auto : BOOL;
  Manual : BOOL;
  Stop : BOOL;
END_VAR

Motor := Start OR (Motor AND (Auto OR Manual) AND NOT Stop);

END_PROGRAM

PROGRAM Main
VAR
  Fan : BOOL;
  StartLocal : BOOL;
  StartRemote : BOOL;
  Stop : BOOL;
END_VAR

Fan := (StartLocal OR StartRemote) OR (Fan AND NOT Stop);

END_PROGRAM

PROGRAM Main
VAR
  Mixer : BOOL;
  Start : BOOL;
  SelA : BOOL;
  SelB : BOOL;
  Stop : BOOL;
END_VAR

Mixer := Start OR (Mixer AND (SelA XOR SelB) AND NOT Stop);

END_PROGRAM

PROGRAM Main
VAR
  Motor : BOOL;
  Start : BOOL;
  Stop : BOOL;
  Overload : BOOL;
END_VAR

Motor := Start OR (Motor AND NOT (Stop OR Overload));

END_PROGRAM

PROGRAM Main
VAR
  Motor : BOOL;
  Start : BOOL;
  Stop : BOOL;
  Reset : BOOL;
END_VAR

Motor := Start OR (Motor AND NOT (Stop OR Reset));

END_PROGRAM

PROGRAM Main
VAR
  Motor1 : BOOL;
  Start1 : BOOL;
  Stop1 : BOOL;
  Motor2 : BOOL;
  Start2 : BOOL;
  Stop2 : BOOL;
END_VAR

Motor1 := Start1 OR (Motor1 AND NOT Stop1);
Motor2 := Start2 OR (Motor2 AND NOT Stop2);

END_PROGRAM

PROGRAM Main
VAR
  MotorFwd : BOOL;
  StartFwd : BOOL;
  MotorRev : BOOL;
  Stop : BOOL;
  StartRev : BOOL;
END_VAR

MotorFwd := StartFwd OR (MotorFwd AND NOT MotorRev AND NOT Stop);
MotorRev := StartRev OR (MotorRev AND NOT MotorFwd AND NOT Stop);

END_PROGRAM

PROGRAM Main
VAR
  MotorFwd : BOOL;
  StartFwd : BOOL;
  MotorRev : BOOL;
  Stop : BOOL;
  StartRev : BOOL;
END_VAR

MotorFwd := (StartFwd AND NOT MotorRev) OR (MotorFwd AND NOT Stop);
MotorRev := (StartRev AND NOT MotorFwd) OR (MotorRev AND NOT Stop);

END_PROGRAM

PROGRAM Main
VAR
  Motor : BOOL;
  Start : BOOL;
  Auto : BOOL;
  Stop : BOOL;
END_VAR

Motor := (Start AND Auto) OR (Motor AND NOT Stop);

END_PROGRAM

PROGRAM Main
VAR
  StartOK : BOOL;
  StartPB : BOOL;
  EStop : BOOL;
  Motor : BOOL;
  StopPB : BOOL;
END_VAR

StartOK := StartPB AND NOT EStop;
Motor := StartOK OR (Motor AND NOT StopPB);

END_PROGRAM

PROGRAM Main
VAR
  Motor : BOOL;
  Start : BOOL;
  Stop_NC : BOOL;
END_VAR

Motor := Start OR (Motor AND Stop_NC);

END_PROGRAM

PROGRAM Main
VAR
  Motor : BOOL;
  Start : BOOL;
  Stop : BOOL;
  Q_Motor : BOOL;
END_VAR

Motor := Start OR (Motor AND NOT Stop);
Q_Motor := Motor;

END_PROGRAM

PROGRAM Main
VAR
  Motor : BOOL;
  Start : BOOL;
  Stop : BOOL;
  RunLamp : BOOL;
END_VAR

Motor := Start OR (Motor AND NOT Stop);
RunLamp := Motor AND NOT Stop;

END_PROGRAM

PROGRAM Main
VAR
  Motor : BOOL;
  Start : BOOL;
  Stop : BOOL;
  Ready : BOOL;
END_VAR

Motor := Start OR (Motor AND NOT Stop);
Ready := NOT Motor AND NOT Stop;

END_PROGRAM

PROGRAM Main
VAR
  Motor : BOOL;
  Start : BOOL;
  Stop : BOOL;
  Warning : BOOL;
END_VAR

Motor := Start OR (Motor AND NOT Stop);
IF Motor AND Stop THEN
  Warning := TRUE;
END_IF;

END_PROGRAM

PROGRAM Main
VAR
  Motor : BOOL;
  Start : BOOL;
  Stop : BOOL;
  HourMeter : BOOL;
  RunTimer : TON;
END_VAR

Motor := Start OR (Motor AND NOT Stop);
RunTimer(IN := Motor AND NOT Stop, PT := T#10S);
HourMeter := RunTimer.Q;

END_PROGRAM

PROGRAM Main
VAR
  Stop : BOOL;
  Motor : BOOL;
  Start : BOOL;
END_VAR

IF Stop THEN
  Motor := FALSE;
END_IF;
Motor := Start OR (Motor AND NOT Stop);

END_PROGRAM

PROGRAM Main
VAR
  TripperConveyor : BOOL;
  Start : BOOL;
  Stop : BOOL;
END_VAR

TripperConveyor := Start OR (TripperConveyor AND NOT Stop);

END_PROGRAM

PROGRAM Main
VAR
  AsphaltPump : BOOL;
  Start : BOOL;
  Stop : BOOL;
  Q_Pump : BOOL;
END_VAR

AsphaltPump := Start OR (AsphaltPump AND NOT Stop);
Q_Pump := AsphaltPump;

END_PROGRAM

PROGRAM Main
VAR
  FlightConveyor : BOOL;
  Start : BOOL;
  Stop : BOOL;
END_VAR

FlightConveyor := Start OR (FlightConveyor AND NOT Stop);

END_PROGRAM

PROGRAM Main
VAR
  Clamp : BOOL;
  Start : BOOL;
  Stop : BOOL;
END_VAR

Clamp := Start OR (Clamp AND NOT Stop);

END_PROGRAM

PROGRAM Main
VAR
  Motor : BOOL;
  Start : BOOL;
  Stop : BOOL;
  EStop : BOOL;
END_VAR

Motor := (Start OR (Motor AND NOT Stop)) AND NOT EStop;

END_PROGRAM

PROGRAM Main
VAR
  Motor : BOOL;
  StartLocal : BOOL;
  StartRemote : BOOL;
  Stop : BOOL;
END_VAR

Motor := StartLocal OR StartRemote OR (Motor AND NOT Stop);

END_PROGRAM

PROGRAM Main
VAR
  Start : BOOL;
  StartPB : BOOL;
  HmiStart : BOOL;
  Motor : BOOL;
  Stop : BOOL;
END_VAR

Start := StartPB OR HmiStart;
Motor := Start OR (Motor AND NOT Stop);
HmiStart := FALSE;

END_PROGRAM

PROGRAM Main
VAR
  Motor : BOOL;
  Start : BOOL;
  EStop : BOOL;
  Stop : BOOL;
END_VAR

Motor := (Start AND NOT EStop) OR (Motor AND NOT Stop AND NOT EStop);

END_PROGRAM

PROGRAM Main
VAR
  Motor : BOOL;
  OnPB : BOOL;
  OffPB : BOOL;
END_VAR

Motor := OnPB OR (Motor AND NOT OffPB);

END_PROGRAM

PROGRAM Main
VAR
  StartPB : BOOL;
  StopPB : BOOL;
  Motor : BOOL;
  Latch : SR;
END_VAR

Latch(SET1 := StartPB, RESET := StopPB);
Motor := Latch.Q1;

END_PROGRAM

PROGRAM Main
VAR
  motor : BOOL;
  start : BOOL;
  or : BOOL;
  and : BOOL;
  not : BOOL;
  stop : BOOL;
END_VAR

motor := start or (motor and not stop);

END_PROGRAM

PROGRAM Main
VAR
  Motor : BOOL;
  Start : BOOL;
  Stop : BOOL;
  EStop : BOOL;
END_VAR

Motor := Start OR (Motor AND NOT Stop) AND NOT EStop;

END_PROGRAM

PROGRAM Main
VAR
  Motor : BOOL;
  Start : BOOL;
  Stop_OK : BOOL;
  Overload_OK : BOOL;
END_VAR

Motor := Start OR (Motor AND Stop_OK AND Overload_OK);

END_PROGRAM

PROGRAM Main
VAR
  Start : BOOL;
  Motor : BOOL;
  Stop : BOOL;
END_VAR

IF Start THEN
  Motor := TRUE;
ELSIF Stop THEN
  Motor := FALSE;
END_IF;

END_PROGRAM

