PROGRAM Main
VAR
  Motor : BOOL;
  Start : BOOL;
  Stop : BOOL;
  Auto : BOOL;
  Manual : BOOL;
  Jog : BOOL;
END_VAR

Motor := Start OR (Motor AND NOT Stop AND (Auto OR (Manual AND Jog)));

END_PROGRAM

PROGRAM Main
VAR
  Motor : BOOL;
  Start : BOOL;
  Auto : BOOL;
  Hand : BOOL;
  Stop : BOOL;
  Fault : BOOL;
END_VAR

Motor := (Start AND (Auto OR Hand)) OR (Motor AND NOT Stop AND NOT Fault);

END_PROGRAM

PROGRAM Main
VAR
  Motor : BOOL;
  Start : BOOL;
  Stop : BOOL;
  EmergencyStop : BOOL;
  OverloadTrip : BOOL;
END_VAR

Motor := Start OR (Motor AND NOT Stop AND NOT EmergencyStop AND NOT OverloadTrip);

END_PROGRAM

const int START_PIN = 2;
const int STOP_PIN = 3;
const int MOTOR_PIN = 8;
bool motorOn = false;

void setup() {
  pinMode(START_PIN, INPUT_PULLUP);
  pinMode(STOP_PIN, INPUT_PULLUP);
  pinMode(MOTOR_PIN, OUTPUT);
}

void loop() {
  bool startPressed = digitalRead(START_PIN) == LOW;
  bool stopPressed = digitalRead(STOP_PIN) == LOW;

  motorOn = startPressed || (motorOn && !stopPressed);

  digitalWrite(MOTOR_PIN, motorOn ? HIGH : LOW);
}

