const int FWD_BTN = 2;
const int REV_BTN = 3;
const int STOP_PIN = 4;
const int FWD_OUT = 8;
const int REV_OUT = 9;
bool fwdOn = false;
bool revOn = false;

void setup() {
  pinMode(FWD_BTN, OUTPUT);
  pinMode(REV_BTN, OUTPUT);
  pinMode(STOP_PIN, INPUT_PULLUP);
  pinMode(FWD_OUT, OUTPUT);
  pinMode(REV_OUT, OUTPUT);
}

void loop() {
  bool fwdStart = digitalRead(FWD_BTN) == LOW;
  bool revStart = digitalRead(REV_BTN) == LOW;
  bool stopPressed = digitalRead(STOP_PIN) == LOW;

  fwdOn = fwdStart || (fwdOn && !revOn && !stopPressed);
  revOn = revStart || (revOn && !fwdOn && !stopPressed);

  digitalWrite(FWD_OUT, fwdOn);
  digitalWrite(REV_OUT, revOn);
}

