const int START_PIN = 2;
const int STOP_PIN = 3;
const int MOTOR_PIN = 8;
bool motorOn = false;
bool startPressed = false;
bool stopPressed = false;

void setup() {
  pinMode(START_PIN, INPUT_PULLUP);
  pinMode(STOP_PIN, INPUT_PULLUP);
  pinMode(MOTOR_PIN, OUTPUT);
}

void loop() {
  startPressed = digitalRead(START_PIN) == LOW;
  stopPressed = digitalRead(STOP_PIN) == LOW;

  if (stopPressed) motorOn = false;
  updateMotor();

  digitalWrite(MOTOR_PIN, motorOn ? HIGH : LOW);
}

void updateMotor() {
  motorOn = startPressed || (motorOn && !stopPressed);
}

