PROGRAM Main
VAR
  RunReq : BOOL;
  Start : BOOL;
  Stop : BOOL;
  Overload : BOOL;
  Motor : BOOL;
END_VAR

RunReq := Start OR (RunReq AND NOT Stop);
IF Stop OR Overload THEN
  Motor := FALSE;
ELSIF RunReq THEN
  Motor := TRUE;
END_IF;

END_PROGRAM

PROGRAM Main
VAR
  Permissive : BOOL;
  Stop : BOOL;
  Overload : BOOL;
  Latch : BOOL;
  Start : BOOL;
  Motor : BOOL;
END_VAR

Permissive := NOT Stop AND NOT Overload;
Latch := Start OR (Latch AND NOT Stop);
Motor := Latch AND Permissive;

END_PROGRAM

const int START_PIN = 2;
const int STOP_PIN = 3;
const int MOTOR_PIN = 8;
bool motorOn = false;
bool runReq = false;

void setup() {
  pinMode(START_PIN, INPUT_PULLUP);
  pinMode(STOP_PIN, INPUT_PULLUP);
  pinMode(MOTOR_PIN, OUTPUT);
}

void loop() {
  bool startPressed = digitalRead(START_PIN) == LOW;
  bool stopPressed = digitalRead(STOP_PIN) == LOW;

  runReq = startPressed || (runReq && !stopPressed);
  if (stopPressed) motorOn = false;
  else if (runReq) motorOn = true;

  digitalWrite(MOTOR_PIN, motorOn ? HIGH : LOW);
}

